static int name_in_list(char list[][MAX_IDENT_LEN], int count, const char *name) {
    for (int i = 0; i < count; i++) if (strcmp(list[i], name) == 0) return 1;
    return 0;
}
static void add_name(char list[][MAX_IDENT_LEN], int *count, const char *name) {
    if (!name_in_list(list, *count, name)) {
        strncpy(list[*count], name, MAX_IDENT_LEN - 1);
        list[*count][MAX_IDENT_LEN - 1] = '\\0';
        (*count)++;
    }
}
static void collect_bound_names(ASTNode *node, char names[][MAX_IDENT_LEN], int *count) {
    if (!node) return;
    switch (node->type) {
        case NODE_LET: add_name(names, count, node->data.let.name); break;
        case NODE_BLOCK:
            for (int i = 0; i < node->data.block.stmts.count; i++)
                collect_bound_names(node->data.block.stmts.items[i], names, count);
            break;
        case NODE_IF:
            collect_bound_names(node->data.if_stmt.then_b, names, count);
            collect_bound_names(node->data.if_stmt.else_b, names, count);
            break;
        case NODE_WHILE: collect_bound_names(node->data.while_stmt.body, names, count); break;
        case NODE_FOR:
            if (node->data.for_stmt.init) collect_bound_names(node->data.for_stmt.init, names, count);
            collect_bound_names(node->data.for_stmt.body, names, count);
            break;
        case NODE_FOREACH:
            add_name(names, count, node->data.foreach_stmt.var);
            collect_bound_names(node->data.foreach_stmt.body, names, count);
            break;
        case NODE_FUNC: add_name(names, count, node->data.func.name); break;
        case NODE_CLOSURE: break;
        default: break;
    }
}
